% Problem-section file following ../_template.tex.
\section{Regularized less-noisy channels beyond degradability}
\label{sec:problem-52}

\paragraph{Problem.}
Does there exist a finite-dimensional regularized less-noisy quantum channel
that is not degradable?  Let
$\mathcal T:\mathcal L(\mathcal H_A)\to\mathcal L(\mathcal H_B)$ have a
Stinespring isometry
$V:\mathcal H_A\to\mathcal H_B\otimes\mathcal H_E$, defining the channel and
one complementary channel by
\begin{equation}
  \mathcal T(\rho)=\operatorname{Tr}_E(V\rho V^\dagger),
  \qquad
  \mathcal T^c(\rho)=\operatorname{Tr}_B(V\rho V^\dagger).
  \label{eq:p52-channel-complement}
\end{equation}
Equation~\eqref{eq:p52-channel-complement} fixes the complementary-channel
notation; changing the Stinespring representation only changes
$\mathcal T^c$ by an output isometry.

The channel $\mathcal T$ is degradable if there exists a channel
$\mathcal D:\mathcal L(\mathcal H_B)\to\mathcal L(\mathcal H_E)$ satisfying
\begin{equation}
  \mathcal T^c=\mathcal D\circ\mathcal T.
  \label{eq:p52-degradable}
\end{equation}
Thus Eq.~\eqref{eq:p52-degradable} requires exact, rather than approximate,
degradability.

For a channel $\mathcal N:A\to B$ with complement $\mathcal N^c:A\to E$,
let
$\omega_{XBE}:=\sum_x p_x\lvert x\rangle\!\langle x\rvert_X\otimes
V_{\mathcal N}\rho_A^xV_{\mathcal N}^\dagger$ for a finite cq ensemble
$\{p_x,\rho_A^x\}$.  Define its one-shot private information and private
capacity by
\begin{equation}
  \begin{aligned}
    \mathcal C_p^{(1)}(\mathcal N)
      &:=\max_{\{p_x,\rho_A^x\}}
          \bigl[I(X;B)_\omega-I(X;E)_\omega\bigr],\\
    \mathcal C_p(\mathcal N)
      &:=\sup_{n\ge1}\frac1n
          \mathcal C_p^{(1)}(\mathcal N^{\otimes n}).
  \end{aligned}
  \label{eq:p52-private-capacity}
\end{equation}
The regularization in Eq.~\eqref{eq:p52-private-capacity} distinguishes the
question from its single-letter counterpart.  In particular, define
\begin{equation}
  \mathfrak D
    :=\{\mathcal T:\mathcal T\text{ satisfies
        Eq.~\eqref{eq:p52-degradable}}\}.
  \label{eq:p52-degradable-class}
\end{equation}
\begin{equation}
  \mathfrak L_1
    :=\{\mathcal T:\mathcal C_p^{(1)}(\mathcal T^c)=0\}.
  \label{eq:p52-one-shot-less-noisy-class}
\end{equation}
\begin{equation}
  \mathfrak L_\infty
    :=\{\mathcal T:\mathcal C_p(\mathcal T^c)=0\}.
  \label{eq:p52-regularized-less-noisy-class}
\end{equation}
\begin{equation}
  \mathfrak D\subseteq\mathfrak L_\infty\subseteq\mathfrak L_1.
  \label{eq:p52-less-noisy-inclusions}
\end{equation}
A channel in $\mathfrak L_\infty$, as defined in
Eq.~\eqref{eq:p52-regularized-less-noisy-class}, is regularized less noisy.
The problem is whether the first inclusion in
Eq.~\eqref{eq:p52-less-noisy-inclusions} is strict.

\subsection*{Status}

Unsolved

\subsection*{Source}

Belzig, Gao, Smith, and Wu explicitly state that it remains open whether a
regularized less-noisy channel can fail to be degradable
\sourcecite{ref:p52-belzig-et-al}{BGSW25}.  Hirche and Leditzky previously
isolated the same strict-inclusion question and related it to superactivation
of private capacity \sourcecite{ref:p52-hirche-leditzky}{HL23}.

\subsection*{Progress}

\begin{itemize}
  \item Data processing proves
  $\mathfrak D\subseteq\mathfrak L_\infty$.  Watanabe showed that regularized
  less-noisy channels have single-letter quantum and private capacities,
  $\mathcal Q(\mathcal T)=\mathcal C_p(\mathcal T)
  =\mathcal Q^{(1)}(\mathcal T)$
  \sourcecite{ref:p52-watanabe}{Wat12}.  Hirche and Leditzky further proved
  that superactivation of private capacity would imply
  $\mathfrak D\subsetneq\mathfrak L_\infty$; neither result decides whether
  the inclusion is strict \sourcecite{ref:p52-hirche-leditzky}{HL23}.

  \item Belzig et al. constructed explicit flagged mixtures of qubit
  amplitude-damping channels that belong to
  $\mathfrak L_1\setminus\mathfrak D$, including the parameter point
  $(p,\gamma_1,\gamma_2)=(0.75,0.2,0.81)$.  This proves
  $\mathfrak D\subsetneq\mathfrak L_1$, but the construction's membership in
  $\mathfrak L_\infty$ is unknown and therefore does not settle
  Eq.~\eqref{eq:p52-less-noisy-inclusions}
  \sourcecite{ref:p52-belzig-et-al}{BGSW25}.

  \item Smith and Wu derived a sufficient condition under which a flagged
  mixture of degradable and antidegradable channels is regularized less noisy
  while remaining nondegradable.  For their amplitude-damping candidates, the
  condition reduces to strict positivity of a multi-copy comparison
  coefficient; they leave that positivity unproved.  Their construction is
  therefore a conditional route to a separation, not a counterexample
  \sourcecite{ref:p52-smith-wu}{SW25}.
\end{itemize}

